class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            cur = []
            for j in range(i, n):
                cur.append(nums[j])
                s = sorted(cur)
                if s[(j - i) // 2] == k:
                    ans += 1
        return ans

