class Solution {
public:
    int countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            vector<int> cur;
            for (int j = i; j < n; j++) {
                cur.push_back(nums[j]);
                vector<int> s = cur;
                sort(s.begin(), s.end());
                if (s[(j - i) / 2] == k) ans++;
            }
        }
        return ans;
    }
};

