        for (int i = 0; i < n; i++) {
            List<Integer> cur = new ArrayList<>();
            for (int j = i; j < n; j++) {
                cur.add(nums[j]);
                List<Integer> s = new ArrayList<>(cur);
                Collections.sort(s);
                if (s.get((j - i) / 2) == k) ans++;
