class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        pos = nums.index(k)
        cnt = {0: 1}
        bal = 0
        for i in range(pos - 1, -1, -1):
            bal += 1 if nums[i] > k else -1
            cnt[bal] = cnt.get(bal, 0) + 1
        ans = 0
        bal = 0
        for i in range(pos, len(nums)):
            bal += 1 if nums[i] > k else -1
            ans += cnt.get(bal, 0) + cnt.get(bal - 1, 0)
        return ans

