class Solution {
public:
    int countSubarrays(vector<int>& nums, int k) {
        int n = nums.size(), pos = 0;
        for (int i = 0; i < n; i++) if (nums[i] == k) pos = i;
        unordered_map<int, int> cnt;
        cnt[0] = 1;
        int bal = 0;
        for (int i = pos - 1; i >= 0; i--) {
            bal += nums[i] > k ? 1 : -1;
            cnt[bal]++;
        }
        long long ans = 0;
        bal = 0;
        for (int i = pos; i < n; i++) {
            bal += nums[i] > k ? 1 : -1;
            auto it = cnt.find(bal);
            if (it != cnt.end()) ans += it->second;
            it = cnt.find(bal - 1);
            if (it != cnt.end()) ans += it->second;
        }
        return (int) ans;
    }
};

