class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length, pos = 0;
        for (int i = 0; i < n; i++) if (nums[i] == k) pos = i;
        Map<Integer, Integer> cnt = new HashMap<>();
        cnt.put(0, 1);
        int bal = 0;
        for (int i = pos - 1; i >= 0; i--) {
            bal += nums[i] > k ? 1 : -1;
            cnt.merge(bal, 1, Integer::sum);
        }
        long ans = 0;
        bal = 0;
        for (int i = pos; i < n; i++) {
            bal += nums[i] > k ? 1 : -1;
            ans += cnt.getOrDefault(bal, 0);
            ans += cnt.getOrDefault(bal - 1, 0);
        }
        return (int) ans;
    }
}

